#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    // Place elements 1..n one by one at positions 0..n-1
    for(int i=0;i<n-1;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;

        // Step 1: bring p[j] to position 0
        if(j>0){
            if(j==n-1){
                // y=1, x=1: suffix=[p[n-1]], prefix=[p[0]], middle=[p[1]..p[n-2]]
                if(n>=3) do_op(1,1);
                else continue; // n==2, just do one op
            } else {
                // x=j, y=n-j: suffix=p[j..n-1] to front. But need x+y<n => j+(n-j)=n not <n. 
                // So use x=1, y=n-j if 1+(n-j)<n => j>1
                if(j>1){
                    do_op(1, n-j); // p[j] goes to position 0
                } else {
                    // j==1: move to end first, then to front
                    // x=1,y=1 swaps first and last conceptually
                    if(n>=3){
                        do_op(1, n-2); // moves p[2..n-1] to front, p[1] stays in middle? No...
                        // Let me just swap to get j!=1
                        // Actually: x=2, y=n-2 if 2+(n-2)<n => false. 
                        // x=1,y=1: [p[n-1]][p[1]..p[n-2]][p[0]]
                        do_op(1,1);
                        i--; continue;
                    }
                }
            }
        }
        // Step 2: now p[0]==i+1 (hopefully), bring to position i
        if(i>0 && p[0]==i+1){
            // x=i, y=1: [p[n-1]][p[i]..p[n-2]][p[0]..p[i-1]]
            // That puts p[0] at position n-1, not i. 
            // Instead: x=1, y=n-1-i if 1+(n-1-i)<n => i>0
            do_op(1, n-1-i);
            // [p[n-1-i+1-1]..wait] = [p[i]..p[n-1]][p[1]..p[i-1]][p[0]]
            // p[0] goes to position n-1. Not right either. Hmm let me just retry.
            // Actually after do_op(1, n-1-i): suffix=p[i+1..n-1](len n-1-i), mid=p[1..i], prefix=p[0]
            // result: [p[i+1]..p[n-1]] [p[1]..p[i]] [p[0]]  => p[0] at end. Not helpful.
            // Correct: x=i+1, y ... no.  Let me just not do step2 and retry.
        }
        if((int)ops.size()>4*n) break;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
